func:
const raw = (msg.error && msg.error.message) || '';
let status = Number(msg.statusCode);
let code = msg.errorCode;
let message = msg.errorMessage;

if (!(status >= 400 && status < 600)) {
    if (/ER_DUP_ENTRY|Duplicate entry/.test(raw)) {
        status = 409;
        code = 'CONFLICT';
        message = 'ข้อมูลนี้มีอยู่แล้ว';
    } else {
        status = 500;
    }
}
if (status >= 500 && !code) {
    const source = msg.error && msg.error.source ? `${msg.error.source.type}:${msg.error.source.name || msg.error.source.id}` : '';
    node.warn(`${msg.req ? msg.req.method + ' ' + msg.req.originalUrl : ''} -> ${status} [${source}] ${raw}`);
    code = 'INTERNAL_ERROR';
    message = 'เกิดข้อผิดพลาดในระบบ กรุณาลองใหม่';
}

// Nothing to answer (e.g. background job or response already sent)
if (!msg.res) return null;

msg.statusCode = status;
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = { error: { code: code || 'ERROR', message: message || 'เกิดข้อผิดพลาด' } };
if (msg.errorDetails) msg.payload.error.details = msg.errorDetails;
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const jwt = global.get('jwt');
const header = (msg.req && msg.req.headers.authorization) || '';
const match = /^Bearer\s+(\S+)$/i.exec(header);
if (!match) return fail(401, 'UNAUTHORIZED', 'กรุณาเข้าสู่ระบบ');

let claims;
try {
    claims = jwt.verify(match[1], env.get('JWT_SECRET'), { algorithms: ['HS256'] });
} catch (e) {
    return fail(401, 'UNAUTHORIZED', 'เซสชันหมดอายุ กรุณาเข้าสู่ระบบใหม่');
}
if (claims.typ !== 'access' || !/^\d+$/.test(String(claims.sub))) {
    return fail(401, 'UNAUTHORIZED', 'โทเคนไม่ถูกต้อง');
}

msg.topic = 'SELECT id, email, role, status, profile_completed FROM users WHERE id = ?';
msg.payload = [Number(claims.sub)];
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const row = msg.payload[0];
if (!row) return fail(401, 'UNAUTHORIZED', 'ไม่พบบัญชีผู้ใช้ กรุณาเข้าสู่ระบบใหม่');
if (row.status !== 'active') return fail(403, 'ACCOUNT_SUSPENDED', 'บัญชีนี้ถูกระงับการใช้งาน');

const allowed = String(env.get('ROLES') || '').split(',').map((s) => s.trim()).filter(Boolean);
if (allowed.length && !allowed.includes(row.role)) {
    return fail(403, 'FORBIDDEN', 'คุณไม่มีสิทธิ์ใช้งานส่วนนี้');
}
if (String(env.get('REQUIRE_PROFILE')) === 'true' && row.role !== 'admin' && !row.profile_completed) {
    return fail(403, 'PROFILE_INCOMPLETE', 'กรุณากรอกข้อมูลโปรไฟล์ให้ครบก่อน');
}

msg.user = { id: row.id, email: row.email, role: row.role, profileCompleted: !!row.profile_completed };
msg.payload = msg.req.body;
delete msg.topic;
return msg;

msg.topic = `SELECT u.id, u.email, u.role, u.status, u.profile_completed, u.pdpa_accepted_at,
       u.password_hash IS NOT NULL AS has_password, u.google_id IS NOT NULL AS has_google,
       sp.user_id IS NOT NULL AS has_seeker_profile, sp.full_name, sp.avatar_file,
       s.id AS shop_id, s.name AS shop_name, s.verify_status
FROM users u
LEFT JOIN seeker_profiles sp ON sp.user_id = u.id
LEFT JOIN shops s ON s.owner_user_id = u.id
WHERE u.id = ?`;
msg.payload = [msg.sessionUserId];
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const r = msg.payload[0];
if (!r) return fail(401, 'UNAUTHORIZED', 'ไม่พบบัญชีผู้ใช้');

let step = 'done';
if (r.role !== 'admin') {
    if (!r.role) step = 'role';
    else if ((r.role === 'seeker' && !r.has_seeker_profile) || (r.role === 'shop' && !r.shop_id)) step = 'profile';
    else if (!r.pdpa_accepted_at || !r.profile_completed) step = 'terms';
}

msg.sessionUser = {
    id: r.id,
    email: r.email,
    role: r.role,
    status: r.status,
    hasPassword: !!r.has_password,
    hasGoogle: !!r.has_google,
    profileCompleted: step === 'done',
    onboardingStep: step,
    displayName: r.full_name || r.shop_name || null,
    avatarPath: r.avatar_file ? 'avatars/' + r.avatar_file : null,
    shop: r.shop_id ? { id: r.shop_id, name: r.shop_name, verifyStatus: r.verify_status } : null,
};

if (String(env.get('ISSUE_TOKEN')) === 'true') {
    const jwt = global.get('jwt');
    msg.sessionToken = jwt.sign({ typ: 'access' }, env.get('JWT_SECRET'), {
        subject: String(r.id),
        expiresIn: env.get('JWT_EXPIRES_IN') || '7d',
        algorithm: 'HS256',
    });
}
delete msg.topic;
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const b = msg.req.body || {};
const email = typeof b.email === 'string' ? b.email.trim().toLowerCase() : '';
const password = typeof b.password === 'string' ? b.password : '';

if (email.length > 255 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return fail(400, 'VALIDATION_ERROR', 'รูปแบบอีเมลไม่ถูกต้อง');
}
if (password.length < 8 || Buffer.byteLength(password) > 72 || !/[A-Za-z]/.test(password) || !/\d/.test(password)) {
    return fail(400, 'VALIDATION_ERROR', 'รหัสผ่านต้องยาว 8 ตัวขึ้นไป และมีทั้งตัวอักษรและตัวเลข');
}

msg.ctx = { email, password };
msg.topic = 'SELECT id FROM users WHERE email = ?';
msg.payload = [email];
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

if (msg.payload.length) return fail(409, 'EMAIL_TAKEN', 'อีเมลนี้ถูกใช้สมัครแล้ว');

const bcrypt = global.get('bcrypt');
bcrypt.hash(msg.ctx.password, 10).then((hash) => {
    msg.topic = 'INSERT INTO users (email, password_hash, last_login_at) VALUES (?, ?, NOW())';
    msg.payload = [msg.ctx.email, hash];
    delete msg.ctx.password;
    node.send(msg);
}).catch((err) => node.error(err, msg));
return null;

msg.sessionUserId = msg.payload.insertId;
msg.statusCode = 201;
return msg;

msg.statusCode = msg.statusCode || 200;
msg.payload = { token: msg.sessionToken, user: msg.sessionUser };
return msg;

