function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const b = msg.req.body || {};
const email = typeof b.email === 'string' ? b.email.trim().toLowerCase() : '';
const password = typeof b.password === 'string' ? b.password : '';
if (!email || !password) return fail(400, 'VALIDATION_ERROR', 'กรุณากรอกอีเมลและรหัสผ่าน');

msg.ctx = { password };
msg.topic = 'SELECT id, password_hash, status FROM users WHERE email = ?';
msg.payload = [email];
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

// Compare against a dummy hash when the user is missing so timing does not reveal accounts
const DUMMY_HASH = '$2a$10$hi7qVmnwH2TwfvT2fMvWReaWpE5Yk2BZzZOzs7AskkqB4G/E5zfr.';
const bcrypt = global.get('bcrypt');
const row = msg.payload[0];
const password = msg.ctx.password;
delete msg.ctx.password;

bcrypt.compare(password, (row && row.password_hash) || DUMMY_HASH).then((ok) => {
    if (!row || !row.password_hash || !ok) {
        return fail(401, 'INVALID_CREDENTIALS', 'อีเมลหรือรหัสผ่านไม่ถูกต้อง');
    }
    if (row.status !== 'active') return fail(403, 'ACCOUNT_SUSPENDED', 'บัญชีนี้ถูกระงับการใช้งาน');

    msg.sessionUserId = row.id;
    msg.topic = 'UPDATE users SET last_login_at = NOW() WHERE id = ?';
    msg.payload = [row.id];
    node.send(msg);
}).catch((err) => node.error(err, msg));
return null;

msg.statusCode = msg.statusCode || 200;
msg.payload = { token: msg.sessionToken, user: msg.sessionUser };
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const clientId = env.get('GOOGLE_CLIENT_ID');
if (!clientId) return fail(503, 'GOOGLE_NOT_CONFIGURED', 'ระบบยังไม่เปิดให้เข้าสู่ระบบด้วย Google');

const idToken = msg.req.body && msg.req.body.idToken;
if (typeof idToken !== 'string' || !idToken) return fail(400, 'VALIDATION_ERROR', 'ไม่พบข้อมูลจาก Google');

let client = context.get('googleClient');
if (!client) {
    const { OAuth2Client } = global.get('googleAuth');
    client = new OAuth2Client();
    context.set('googleClient', client);
}

// Only data from the verified token is trusted, never anything else the frontend sends
client.verifyIdToken({ idToken, audience: clientId }).then((ticket) => {
    const p = ticket.getPayload();
    if (!p || !p.sub || !p.email || p.email_verified !== true) {
        return fail(401, 'GOOGLE_TOKEN_INVALID', 'ไม่สามารถยืนยันบัญชี Google ได้');
    }
    msg.ctx = { googleId: p.sub, email: p.email.toLowerCase() };
    msg.topic = 'SELECT id, email, google_id, role, status FROM users WHERE google_id = ? OR email = ?';
    msg.payload = [p.sub, msg.ctx.email];
    node.send(msg);
}).catch(() => fail(401, 'GOOGLE_TOKEN_INVALID', 'ไม่สามารถยืนยันบัญชี Google ได้'));
return null;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const { googleId, email } = msg.ctx;
const byGoogle = msg.payload.find((r) => r.google_id === googleId);
const byEmail = msg.payload.find((r) => r.email.toLowerCase() === email);
const user = byGoogle || byEmail;

if (!user) {
    msg.statusCode = 201;
    msg.topic = 'INSERT INTO users (email, google_id, last_login_at) VALUES (?, ?, NOW())';
    msg.payload = [email, googleId];
    return msg;
}

if (user.role === 'admin') {
    return fail(403, 'ADMIN_PASSWORD_ONLY', 'บัญชีแอดมินต้องเข้าสู่ระบบด้วยอีเมลและรหัสผ่าน');
}
if (user.status !== 'active') return fail(403, 'ACCOUNT_SUSPENDED', 'บัญชีนี้ถูกระงับการใช้งาน');

if (!byGoogle) {
    if (user.google_id) {
        return fail(409, 'GOOGLE_ACCOUNT_CONFLICT', 'อีเมลนี้เชื่อมกับบัญชี Google อื่นอยู่แล้ว');
    }
    // Existing email/password account: the user must confirm with the old password
    const jwt = global.get('jwt');
    const linkToken = jwt.sign({ typ: 'google-link', gid: googleId }, env.get('JWT_SECRET'), {
        subject: String(user.id),
        expiresIn: '10m',
        algorithm: 'HS256',
    });
    return fail(409, 'GOOGLE_LINK_REQUIRED', 'อีเมลนี้มีบัญชีอยู่แล้ว กรุณาใส่รหัสผ่านเดิมเพื่อเชื่อมกับ Google', {
        linkToken,
        email: user.email,
    });
}

msg.sessionUserId = user.id;
msg.topic = 'UPDATE users SET last_login_at = NOW() WHERE id = ?';
msg.payload = [user.id];
return msg;

msg.statusCode = msg.statusCode || 200;
msg.payload = { token: msg.sessionToken, user: msg.sessionUser };
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const jwt = global.get('jwt');
const b = msg.req.body || {};
let claims;
try {
    claims = jwt.verify(String(b.linkToken || ''), env.get('JWT_SECRET'), { algorithms: ['HS256'] });
} catch (e) {
    claims = null;
}
if (!claims || claims.typ !== 'google-link' || !claims.gid) {
    return fail(401, 'LINK_TOKEN_INVALID', 'หมดเวลาเชื่อมบัญชี กรุณาเข้าสู่ระบบด้วย Google อีกครั้ง');
}
if (typeof b.password !== 'string' || !b.password) return fail(400, 'VALIDATION_ERROR', 'กรุณากรอกรหัสผ่าน');

msg.ctx = { userId: Number(claims.sub), googleId: claims.gid, password: b.password };
msg.topic = 'SELECT id, password_hash, google_id, role, status FROM users WHERE id = ?';
msg.payload = [msg.ctx.userId];
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const bcrypt = global.get('bcrypt');
const row = msg.payload[0];
const password = msg.ctx.password;
delete msg.ctx.password;
if (!row || !row.password_hash) return fail(401, 'LINK_TOKEN_INVALID', 'ไม่พบบัญชีที่ต้องการเชื่อม');

bcrypt.compare(password, row.password_hash).then((ok) => {
    if (!ok) return fail(401, 'INVALID_CREDENTIALS', 'รหัสผ่านไม่ถูกต้อง');
    if (row.role === 'admin') return fail(403, 'ADMIN_PASSWORD_ONLY', 'บัญชีแอดมินต้องเข้าสู่ระบบด้วยอีเมลและรหัสผ่าน');
    if (row.status !== 'active') return fail(403, 'ACCOUNT_SUSPENDED', 'บัญชีนี้ถูกระงับการใช้งาน');
    if (row.google_id) return fail(409, 'GOOGLE_ACCOUNT_CONFLICT', 'บัญชีนี้เชื่อมกับ Google แล้ว');

    msg.sessionUserId = row.id;
    msg.topic = 'UPDATE users SET google_id = ?, last_login_at = NOW() WHERE id = ? AND google_id IS NULL';
    msg.payload = [msg.ctx.googleId, row.id];
    node.send(msg);
}).catch((err) => node.error(err, msg));
return null;

msg.statusCode = msg.statusCode || 200;
msg.payload = { token: msg.sessionToken, user: msg.sessionUser };
return msg;

msg.statusCode = 200;
msg.payload = { user: msg.sessionUser };
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const role = msg.payload && msg.payload.role;
if (role !== 'seeker' && role !== 'shop') return fail(400, 'VALIDATION_ERROR', 'กรุณาเลือกบทบาท');
if (msg.user.role) return fail(409, 'ROLE_ALREADY_SET', 'เลือกบทบาทไปแล้ว เปลี่ยนไม่ได้');

msg.topic = 'UPDATE users SET role = ? WHERE id = ? AND role IS NULL';
msg.payload = [role, msg.user.id];
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

if (msg.payload.affectedRows !== 1) return fail(409, 'ROLE_ALREADY_SET', 'เลือกบทบาทไปแล้ว เปลี่ยนไม่ได้');
msg.sessionUserId = msg.user.id;
return msg;

msg.statusCode = 200;
msg.payload = { user: msg.sessionUser };
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const b = msg.payload || {};
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const toId = (v) => (Number.isInteger(v) && v > 0 ? v : null);

const fullName = str(b.fullName);
if (!fullName || fullName.length > 150) return fail(400, 'VALIDATION_ERROR', 'กรุณากรอกชื่อ-นามสกุล (ไม่เกิน 150 ตัวอักษร)');

const birthDate = str(b.birthDate);
const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(birthDate);
const bd = m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])) : null;
if (!bd || bd.getUTCMonth() !== +m[2] - 1 || bd.getUTCDate() !== +m[3]) {
    return fail(400, 'VALIDATION_ERROR', 'วันเกิดไม่ถูกต้อง');
}
const today = new Date(Date.now() + 7 * 3600 * 1000); // Asia/Bangkok
let age = today.getUTCFullYear() - +m[1];
if (today.getUTCMonth() + 1 < +m[2] || (today.getUTCMonth() + 1 === +m[2] && today.getUTCDate() < +m[3])) age--;
if (age < 18) return fail(400, 'UNDERAGE', 'ผู้หางานต้องมีอายุ 18 ปีขึ้นไป');
if (age > 100) return fail(400, 'VALIDATION_ERROR', 'วันเกิดไม่ถูกต้อง');

const phone = str(b.phone).replace(/[\s-]/g, '');
if (!/^0\d{8,9}$/.test(phone)) return fail(400, 'VALIDATION_ERROR', 'เบอร์โทรไม่ถูกต้อง');

const lineId = str(b.lineId);
if (lineId && !/^@?[A-Za-z0-9._-]{1,50}$/.test(lineId)) return fail(400, 'VALIDATION_ERROR', 'LINE ID ไม่ถูกต้อง');

const skills = str(b.skills);
const bio = str(b.bio);
if (skills.length > 500) return fail(400, 'VALIDATION_ERROR', 'ทักษะยาวเกิน 500 ตัวอักษร');
if (bio.length > 1000) return fail(400, 'VALIDATION_ERROR', 'แนะนำตัวยาวเกิน 1000 ตัวอักษร');

// Areas: [{ provinceId, districtId|null }]; null district = whole province (wins over its districts)
if (!Array.isArray(b.areas) || b.areas.length < 1 || b.areas.length > 30) {
    return fail(400, 'VALIDATION_ERROR', 'กรุณาเลือกพื้นที่ที่สนใจอย่างน้อย 1 แห่ง');
}
const byProvince = new Map();
for (const a of b.areas) {
    const provinceId = toId(a && a.provinceId);
    const districtId = a && a.districtId !== null && a.districtId !== undefined ? toId(a.districtId) : null;
    if (!provinceId || (a.districtId !== null && a.districtId !== undefined && !districtId)) {
        return fail(400, 'VALIDATION_ERROR', 'ข้อมูลพื้นที่ไม่ถูกต้อง');
    }
    if (!byProvince.has(provinceId)) byProvince.set(provinceId, new Set());
    byProvince.get(provinceId).add(districtId);
}
const areas = [];
for (const [provinceId, districts] of byProvince) {
    if (districts.has(null)) areas.push({ provinceId, districtId: null });
    else for (const districtId of districts) areas.push({ provinceId, districtId });
}

msg.ctx = { fullName, birthDate, phone, lineId: lineId || null, skills: skills || null, bio: bio || null, areas };
const provinceIds = [...byProvince.keys()];
const districtIds = areas.filter((a) => a.districtId).map((a) => a.districtId);
msg.topic = 'SELECT id FROM provinces WHERE id IN (?); SELECT id, province_id FROM districts WHERE id IN (?)';
msg.payload = [provinceIds, districtIds.length ? districtIds : [0]];
return msg;

// Sends a standard error response via the tab's catch node
function fail(status, code, message, details) {
    msg.statusCode = status;
    msg.errorCode = code;
    msg.errorMessage = message;
    if (details) msg.errorDetails = details;
    node.error(message, msg);
    return null;
}

const [provinceRows, districtRows] = msg.payload;
const provinces = new Set(provinceRows.map((r) => r.id));
const districtProvince = new Map(districtRows.map((r) => [r.id, r.province_id]));
const c = msg.ctx;

for (const a of c.areas) {
    if (!provinces.has(a.provinceId)) return fail(400, 'VALIDATION_ERROR', 'ไม่พบจังหวัดที่เลือก');
    if (a.districtId && districtProvince.get(a.districtId) !== a.provinceId) {
        return fail(400, 'VALIDATION_ERROR', 'อำเภอไม่อยู่ในจังหวัดที่เลือก');
    }
}

const uid = msg.user.id;
// Not a transaction: inputs are fully validated above, so the later statements cannot fail on data
