const sj = global.get('sj');
const q = msg.req.query;
const p = (msg.ctx = sj.paging(q));
const statuses = ['unsubmitted', 'pending', 'verified', 'rejected'];
const status = q.status || 'pending';
if (status !== 'all' && !statuses.includes(status)) return fail(400, 'VALIDATION_ERROR', 'สถานะไม่ถูกต้อง');

const where = [];
const params = [];
if (status !== 'all') {
    where.push('s.verify_status = ?');
    params.push(status);
}
const text = typeof q.q === 'string' ? q.q.trim().slice(0, 100) : '';
if (text) {
    const like = '%' + text.replace(/[\\%_]/g, (c) => '\\' + c) + '%';
    where.push('(s.name LIKE ? OR u.email LIKE ?)');
    params.push(like, like);
}
// Pending queue: oldest submission first; other lists: newest shop first
const order = status === 'pending' ? 's.verify_submitted_at ASC, s.id ASC' : 's.created_at DESC, s.id DESC';
msg.topic = `SELECT s.id, s.name, s.image_file, s.verify_status, p.name_th AS province_name, d.name_th AS district_name,
             u.email AS owner_email, u.status AS owner_status,
             DATE_FORMAT(s.verify_submitted_at, '%Y-%m-%d %H:%i:%s') AS verify_submitted_at,
             DATE_FORMAT(s.created_at, '%Y-%m-%d %H:%i:%s') AS created_at
        FROM shops s
        JOIN users u ON u.id = s.owner_user_id
        JOIN provinces p ON p.id = s.province_id
        JOIN districts d ON d.id = s.district_id
        ${where.length ? 'WHERE ' + where.join(' AND ') : ''}
        ORDER BY ${order}
        LIMIT ? OFFSET ?`;
msg.payload = [...params, p.limit, p.offset];
return msg;

