// Validates a job body. Returns { error } or { value }. Schedule dates must not be in the past when given.
function validateJob(b, sj) {
    const str = (v) => (typeof v === 'string' ? v.trim() : '');
    const toId = (v) => (Number.isInteger(v) && v > 0 ? v : null);
    const err = (error) => ({ error });
    const today = sj.today();

    const title = str(b.title);
    if (!title || title.length > 150) return err('กรุณากรอกชื่องาน (ไม่เกิน 150 ตัวอักษร)');
    const description = str(b.description);
    if (!description || description.length > 5000) return err('กรุณากรอกรายละเอียดงาน (ไม่เกิน 5000 ตัวอักษร)');
    const categoryId = toId(b.categoryId);
    if (!categoryId) return err('กรุณาเลือกหมวดหมู่งาน');
    const provinceId = toId(b.provinceId);
    const districtId = toId(b.districtId);
    if (!provinceId || !districtId) return err('กรุณาเลือกจังหวัดและอำเภอ');

    const wage = typeof b.wage === 'number' ? Math.round(b.wage * 100) / 100 : NaN;
    if (!(wage > 0 && wage <= 100000)) return err('ค่าจ้างต้องมากกว่า 0 และไม่เกิน 100,000 บาท');
    if (!['hour', 'day', 'job'].includes(b.wageUnit)) return err('หน่วยค่าจ้างไม่ถูกต้อง');

    const time = /^([01]\d|2[0-3]):[0-5]\d$/;
    if (!time.test(b.startTime || '') || !time.test(b.endTime || '')) return err('เวลาทำงานไม่ถูกต้อง');
    if (b.startTime === b.endTime) return err('เวลาเริ่มและเวลาเลิกงานต้องไม่ซ้ำกัน');

    let startDate = null;
    let endDate = null;
    let workDays;
    if (b.scheduleType === 'dates') {
        if (!sj.parseDate(b.startDate) || !sj.parseDate(b.endDate)) return err('กรุณาเลือกวันเริ่มและวันสิ้นสุดงาน');
        startDate = b.startDate;
        endDate = b.endDate;
        if (endDate < startDate) return err('วันสิ้นสุดต้องไม่ก่อนวันเริ่มงาน');
        if (endDate > sj.addDays(today, 365)) return err('วันทำงานต้องอยู่ภายใน 1 ปี');
        workDays = sj.weekdaysInRange(startDate, endDate);
    } else if (b.scheduleType === 'weekly') {
        if (!Array.isArray(b.workDays) || !b.workDays.length || b.workDays.some((w) => !sj.WEEKDAYS.includes(w))) {
            return err('กรุณาเลือกวันทำงานอย่างน้อย 1 วัน');
        }
        workDays = sj.WEEKDAYS.filter((w) => b.workDays.includes(w));
    } else {
