// Rejects the pending applications of a job that stopped taking applicants, and tells each seeker
async function closePending(db, job) {
    const sj = global.get('sj');
    const [rows] = await db.query("SELECT id, seeker_user_id FROM applications WHERE job_id = ? AND status = 'pending' FOR UPDATE", [job.id]);
    if (!rows.length) return 0;
    await db.query("UPDATE applications SET status = 'rejected', decided_at = NOW() WHERE id IN (?)", [rows.map((r) => r.id)]);
    await sj.notify(db, rows.map((r) => r.seeker_user_id), 'application.rejected',
        `ประกาศ "${job.title}" ปิดรับสมัครแล้ว ใบสมัครของคุณจึงไม่ได้รับการพิจารณา`, '/seeker/applications');
    return rows.length;
}

try {
    const id = routeId();
    if (!id) throw sj.httpError(404, 'NOT_FOUND', 'ไม่พบประกาศนี้');
    const rejected = await sj.tx(async (db) => {
        const [[job]] = await db.query(
            'SELECT j.id, j.title, j.status FROM jobs j JOIN shops s ON s.id = j.shop_id WHERE j.id = ? AND s.owner_user_id = ? FOR UPDATE',
            [id, msg.user.id],
        );
        if (!job) throw sj.httpError(404, 'NOT_FOUND', 'ไม่พบประกาศนี้');
        if (job.status !== 'open') throw sj.httpError(409, 'INVALID_STATE', 'ประกาศนี้ไม่ได้เปิดรับสมัครอยู่');
        await db.query("UPDATE jobs SET status = 'closed' WHERE id = ?", [id]);
        return closePending(db, job);
    });
    msg.statusCode = 200;
    msg.payload = { id, status: 'closed', rejectedApplications: rejected };
    return msg;
} catch (e) {
    if (e instanceof sj.HttpError) return fail(e.status, e.code, e.message, e.details);
    throw e;
}

