async function closePending(db, job) {
    const sj = global.get('sj');
    const [rows] = await db.query("SELECT id, seeker_user_id FROM applications WHERE job_id = ? AND status = 'pending' FOR UPDATE", [job.id]);
    if (!rows.length) return 0;
    await db.query("UPDATE applications SET status = 'rejected', decided_at = NOW() WHERE id IN (?)", [rows.map((r) => r.id)]);
    await sj.notify(db, rows.map((r) => r.seeker_user_id), 'application.rejected',
        `ประกาศ "${job.title}" ปิดรับสมัครแล้ว ใบสมัครของคุณจึงไม่ได้รับการพิจารณา`, '/seeker/applications');
    return rows.length;
}

try {
    const result = await sj.tx(async (db) => {
        const [jobs] = await db.query(
            `SELECT j.id, j.title, s.owner_user_id FROM jobs j JOIN shops s ON s.id = j.shop_id
             WHERE j.status = 'open' AND j.expires_on < CURDATE() FOR UPDATE`,
        );
        if (!jobs.length) return { closedJobs: 0, rejectedApplications: 0 };
        await db.query("UPDATE jobs SET status = 'closed' WHERE id IN (?)", [jobs.map((j) => j.id)]);
        let rejected = 0;
        for (const job of jobs) {
            rejected += await closePending(db, job);
            await sj.notify(db, job.owner_user_id, 'job.expired', `ประกาศ "${job.title}" หมดอายุแล้ว กดต่ออายุได้ถ้ายังรับสมัครอยู่`, `/shop/jobs/${job.id}`);
        }
        return { closedJobs: jobs.length, rejectedApplications: rejected };
    });
    msg.statusCode = 200;
    msg.payload = result;
    return msg;
} catch (e) {
    if (e instanceof sj.HttpError) return fail(e.status, e.code, e.message, e.details);
    throw e;
}

// A job seekers may see in search: open, not expired, schedule not over, shop verified, owner not suspended
const VISIBLE = `j.status = 'open' AND j.expires_on >= CURDATE()
    AND NOT (j.schedule_type = 'dates' AND j.end_date < CURDATE())
    AND s.verify_status = 'verified' AND u.status = 'active'`;
const SHOP_JOINS = `JOIN shops s ON s.id = j.shop_id
JOIN users u ON u.id = s.owner_user_id`;

msg.topic = `SELECT j.province_id, j.district_id, COUNT(*) AS n
        FROM jobs j ${SHOP_JOINS}
        WHERE ${VISIBLE}
        GROUP BY j.province_id, j.district_id`;
msg.payload = [];
return msg;

const provinces = {};
const districts = {};
let total = 0;
for (const r of msg.payload) {
    const n = Number(r.n);
    provinces[r.province_id] = (provinces[r.province_id] || 0) + n;
    districts[r.district_id] = n;
    total += n;
}
msg.statusCode = 200;
msg.headers = { 'Cache-Control': 'public, max-age=60' };
msg.payload = { total, provinces, districts };
return msg;

