// "1,2,3" -> [1, 2, 3] (positive integers only, max 50); null when invalid
function idList(text) {
    if (text === undefined || text === '') return [];
    const parts = String(text).split(',');
    if (parts.length > 50 || parts.some((p) => !/^\d{1,10}$/.test(p))) return null;
    return [...new Set(parts.map(Number))];
}

const sj = global.get('sj');
const q = msg.req.query;
const p = (msg.ctx = sj.paging(q));
const where = [VISIBLE];
const params = [];
const bad = (m) => fail(400, 'VALIDATION_ERROR', m);
const intParam = (v) => (v === undefined || v === '' ? null : /^\d{1,10}$/.test(v) ? Number(v) : NaN);

const provinceId = intParam(q.provinceId);
if (Number.isNaN(provinceId)) return bad('provinceId ไม่ถูกต้อง');
if (provinceId) {
    where.push('j.province_id = ?');
    params.push(provinceId);
}
const districtIds = idList(q.districtIds);
if (!districtIds) return bad('districtIds ไม่ถูกต้อง');
if (districtIds.length) {
    where.push('j.district_id IN (?)');
    params.push(districtIds);
}
const categoryId = intParam(q.categoryId);
if (Number.isNaN(categoryId)) return bad('categoryId ไม่ถูกต้อง');
if (categoryId) {
    where.push('j.category_id = ?');
    params.push(categoryId);
}
if (q.wageUnit) {
    if (!['hour', 'day', 'job'].includes(q.wageUnit)) return bad('wageUnit ไม่ถูกต้อง');
    where.push('j.wage_unit = ?');
    params.push(q.wageUnit);
}
for (const [key, op] of [['wageMin', '>='], ['wageMax', '<=']]) {
    if (q[key] === undefined || q[key] === '') continue;
    const v = Number(q[key]);
    if (!Number.isFinite(v) || v < 0) return bad(key + ' ไม่ถูกต้อง');
    where.push(`j.wage ${op} ?`);
    params.push(v);
}
if (q.workDays) {
    const days = String(q.workDays).split(',');
    if (days.some((d) => !sj.WEEKDAYS.includes(d))) return bad('workDays ไม่ถูกต้อง');
    // SET column as a bit mask: any chosen weekday matches
    where.push('(j.work_days & ?) <> 0');
    params.push(sj.weekdayMask(days));
}
const text = typeof q.q === 'string' ? q.q.trim().slice(0, 100) : '';
if (text) {
    const like = '%' + text.replace(/[\\%_]/g, (c) => '\\' + c) + '%';
    where.push('(j.title LIKE ? OR s.name LIKE ?)');
    params.push(like, like);
}

msg.topic = `SELECT ${JOB_COLUMNS}, 1 AS accepting, s.name AS shop_name, s.image_file AS shop_image
        FROM jobs j ${SHOP_JOINS} ${JOB_JOINS}
        WHERE ${where.join(' AND ')}
        ORDER BY j.created_at DESC, j.id DESC
        LIMIT ? OFFSET ?`;
msg.payload = [...params, p.limit, p.offset];
return msg;

